"""
Leitungs-Tool: erzeugt EINE HTML-Datei mit Bedienfeld.
 - jeden Betreiber (Fremdanlagen) einzeln an/aus + Farbe frei wählbar
 - eigene TransnetBW-Leitungen je Spannungsebene an/aus + Farbe (Standard: 380 rot, 220 hellgrün)
 - Suche, Zoom auf Betreiber, Linienstärke, Hintergrund, Einstellungen werden im Browser gemerkt

Benötigt:  pip install geopandas
Aufruf:    python leitungs_tool.py
Wichtig:   Je Shapefile müssen .shp, .shx, .dbf, .prj, .cpg im selben Ordner liegen.
"""
import colorsys
import json
import re
from pathlib import Path

import geopandas as gpd
import shapely

# ============================ EINSTELLUNGEN ============================
ORDNER = Path(r"C:\Users\trade\Downloads\Lohnabrechnungen")
SHP_FREMD = ORDNER / "Leitungsanlagenabschnitte__Fremdanlagen_Line.shp"
SHP_EIGEN = ORDNER / "LeitungsanlagenabschnitteLine.shp"   # None = weglassen
AUSGABE = ORDNER / "Leitungs_Tool.html"

SPALTE_BETREIBER = "eigentueme"
TRENNEN = True                  # "DB Energie GmbH, Netze BW GmbH" -> zählt bei beiden Betreibern
STANDARD_AN = ["DB Energie GmbH"]            # beim Öffnen eingeschaltet
STANDARD_FARBEN = {"DB Energie GmbH": "#1f5bd6"}

SPALTE_SPANNUNG = "bauspannun"  # wird automatisch gesucht, falls nicht vorhanden
SPANNUNG_FARBEN = {380: "#d62728", 220: "#7ed957"}   # an beim Öffnen; übrige Spannungen grau + aus

# Eigen vs. gemeinschaftlich (eigene Leitungen)
SPALTE_EIGENTUEMER = "eigentueme"   # Eigentümer-Spalte der eigenen Datei (wird gesucht, falls nicht vorhanden)
EIGENER_NAME = "TransnetBW"         # alles andere im Eigentümerfeld = Partner -> gemeinschaftlich
SPALTE_PARTNER = None               # optional: eigene Spalte mit Mitbeteiligten, falls es die gibt

# Parallele Leitungen (nur Darstellung, Koordinaten bleiben unverändert)
#  rausgezoomt: übereinander, untere breiter, obere schmaler | ab ZOOM_NEBENEINANDER: nebeneinander
PARALLEL_ABSTAND_M = 25     # näher als das = gleicher Trassenverlauf
PARALLEL_MIN_M = 150        # Mindestlänge des gemeinsamen Verlaufs (bei kurzen Abschnitten: halbe Länge)
ZOOM_NEBENEINANDER = 13     # ab dieser Zoomstufe nebeneinander (12 = Stadt, 14 = Ortsteil)
# =======================================================================


def laden(pfad):
    gdf = gpd.read_file(pfad)
    if gdf.crs is None:
        gdf = gdf.set_crs(epsg=25832)
    metrisch = list(gdf.to_crs(epsg=25832).geometry)
    gdf = gdf.to_crs(epsg=4326)
    gdf["geometry"] = shapely.transform(gdf.geometry, lambda c: c.round(6))
    gdf.attrs["metrisch"] = metrisch
    for c in gdf.columns:
        if c != "geometry":
            gdf[c] = gdf[c].fillna("").astype(str).replace({"None": "", "nan": "", "NaT": ""})
    return gdf


def spalte_finden(gdf, wunsch, stichwort):
    if wunsch in gdf.columns:
        return wunsch
    kand = [c for c in gdf.columns if stichwort in c.lower()]
    if not kand:
        raise SystemExit(f"Spalte '{wunsch}' nicht gefunden. Vorhanden: {list(gdf.columns)}")
    print(f"Hinweis: nutze Spalte '{kand[0]}' statt '{wunsch}'")
    return kand[0]


def kv(wert):
    m = re.search(r"\d+(?:[.,]\d+)?", str(wert))
    if not m:
        return None
    z = float(m.group().replace(",", "."))
    return round(z / 1000) if z >= 1000 else round(z)


PALETTE = ["#ff7f0e", "#9467bd", "#17becf", "#e377c2", "#8c564b", "#bcbd22", "#f4a261",
           "#2a9d8f", "#6a4c93", "#b5838d", "#e9c46a", "#264653", "#ff006e", "#8338ec"]


def farbe(i):
    if i < len(PALETTE):
        return PALETTE[i]
    r, g, b = colorsys.hls_to_rgb((i * 0.618034) % 1, 0.45, 0.75)
    return "#%02x%02x%02x" % (int(r * 255), int(g * 255), int(b * 255))


def _tangente(g, p):
    if g.geom_type == "MultiLineString":
        g = min(g.geoms, key=lambda x: x.distance(p))
    t = g.project(p)
    a, b = g.interpolate(max(t - 10, 0)), g.interpolate(min(t + 10, g.length))
    dx, dy = b.x - a.x, b.y - a.y
    n = (dx * dx + dy * dy) ** 0.5 or 1
    return dx / n, dy / n


def parallel_analyse(geoms):
    """Welche Leitungen laufen parallel? + einheitliche Laufrichtung, damit 'rechts daneben' überall gleich ist."""
    n = len(geoms)
    tree = shapely.STRtree(geoms)
    puffer = [g.buffer(PARALLEL_ABSTAND_M, cap_style="flat") for g in geoms]
    nb, gegen, abstand = [[] for _ in range(n)], {}, {}
    for i in range(n):
        for j in map(int, tree.query(puffer[i])):
            if j <= i or geoms[i].is_empty or geoms[j].is_empty:
                continue
            teile = [t for t in shapely.get_parts(geoms[j].intersection(puffer[i])) if t.geom_type == "LineString"]
            if not teile:
                continue
            if sum(t.length for t in teile) < max(20, min(PARALLEL_MIN_M, 0.5 * min(geoms[i].length, geoms[j].length))):
                continue
            pkt = max(teile, key=lambda t: t.length).interpolate(0.5, normalized=True)
            (ax, ay), (bx, by) = _tangente(geoms[i], pkt), _tangente(geoms[j], pkt)
            cos = ax * bx + ay * by
            if abs(cos) < 0.85:          # kreuzend
                continue
            nb[i].append(j); nb[j].append(i)
            gegen[(i, j)] = gegen[(j, i)] = cos < 0
            abstand[(i, j)] = abstand[(j, i)] = round(geoms[i].distance(pkt), 1)
    umkehren = [None] * n
    for s in range(n):
        if umkehren[s] is None:
            umkehren[s], stapel = False, [s]
            while stapel:
                c = stapel.pop()
                for k in nb[c]:
                    if umkehren[k] is None:
                        umkehren[k] = umkehren[c] ^ gegen[(c, k)]
                        stapel.append(k)
    return nb, umkehren, abstand


def geojson(gdf):
    return json.loads(gdf.to_json(drop_id=True))


def main():
    daten = {"fremd": None, "eigen": None}

    # ---- Fremdanlagen: Gruppen je Betreiber
    fremd = laden(SHP_FREMD)
    gruppen = {}
    for idx, wert in enumerate(fremd[SPALTE_BETREIBER]):
        namen = [n.strip() for n in re.split(r"[;,]", wert)] if TRENNEN else [wert.strip()]
        for n in [n for n in namen if n] or ["(ohne Angabe)"]:
            gruppen.setdefault(n, []).append(idx)
    reihenfolge = sorted(gruppen, key=lambda n: (n == "(ohne Angabe)", -len(gruppen[n]), n))
    ohne_std = [n for n in reihenfolge if n not in STANDARD_FARBEN]
    daten["fremd"] = {
        "fc": geojson(fremd),
        "gruppen": [{"name": n, "idx": gruppen[n],
                     "farbe": STANDARD_FARBEN.get(n) or farbe(ohne_std.index(n)),
                     "an": n in STANDARD_AN} for n in reihenfolge],
    }
    print(f"Fremdanlagen: {len(fremd)} Abschnitte, {len(gruppen)} Betreiber")

    # ---- Eigene Leitungen: Gruppen je Spannung
    if SHP_EIGEN:
        eigen = laden(SHP_EIGEN)
        sp = spalte_finden(eigen, SPALTE_SPANNUNG, "spann")
        kvs = eigen[sp].map(kv)
        eg = {}
        for idx, k in enumerate(kvs):
            eg.setdefault(k, []).append(idx)
        sortiert = sorted(eg, key=lambda k: -(k or 0))
        # gemeinschaftlich / Partner bestimmen
        if SPALTE_PARTNER:
            quelle, mit_eigen = SPALTE_PARTNER, False
        else:
            quelle, mit_eigen = spalte_finden(eigen, SPALTE_EIGENTUEMER, "eigent"), True
        meta, pz = [], {}
        for wert in eigen[quelle]:
            namen = [n.strip() for n in re.split(r"[;,]", wert) if n.strip()]
            partner = [n for n in namen if EIGENER_NAME.lower() not in n.lower()]
            for n in partner:
                pz[n] = pz.get(n, 0) + 1
            meta.append({"gem": bool(partner), "p": partner})
        pliste = sorted(pz, key=lambda n: (-pz[n], n))
        n_gem = sum(m["gem"] for m in meta)
        print(f"Eigentum aus Spalte '{quelle}': {len(meta) - n_gem} komplett eigen, {n_gem} gemeinschaftlich")
        print("  Beispielwerte: " + " | ".join(eigen[quelle].value_counts().index[:5]))
        if pliste:
            print("  Partner: " + ", ".join(f"{n} ({pz[n]})" for n in pliste[:10]))

        daten["eigen"] = {
            "meta": meta,
            "partner": [{"name": n, "farbe": farbe(i + 1)} for i, n in enumerate(pliste)],  # ohne Orange (Kontrast zur Hervorhebung)
            "fc": geojson(eigen),
            "gruppen": [{"name": f"{k} kV" if k else "(ohne Angabe)", "idx": eg[k],
                         "farbe": SPANNUNG_FARBEN.get(k, "#8a8a8a"),
                         "an": k in SPANNUNG_FARBEN} for k in sortiert],
        }
        print("Eigene Leitungen: " + ", ".join(f"{g['name']}: {len(g['idx'])}" for g in daten["eigen"]["gruppen"]))

    # ---- Parallele Leitungen
    quellen = ([("e", eigen)] if SHP_EIGEN else []) + [("f", fremd)]
    ids = [(k, i) for k, g in quellen for i in range(len(g))]
    nb, umkehren, abstand = parallel_analyse([g for _, gdf in quellen for g in gdf.attrs["metrisch"]])
    fcs = {"e": daten["eigen"]["fc"] if SHP_EIGEN else None, "f": daten["fremd"]["fc"]}
    daten["nb"] = {}
    for n, (k, i) in enumerate(ids):
        if umkehren[n]:
            geom = fcs[k]["features"][i]["geometry"]
            if geom["type"] == "LineString":
                geom["coordinates"].reverse()
            elif geom["type"] == "MultiLineString":
                geom["coordinates"] = [list(reversed(t)) for t in reversed(geom["coordinates"])]
        if nb[n]:
            daten["nb"][f"{k}{i}"] = [[f"{ids[m][0]}{ids[m][1]}", abstand[(n, m)]] for m in nb[n]]
    daten["zoomNeben"] = ZOOM_NEBENEINANDER
    print(f"Parallel: {len(daten['nb'])} Abschnitte verlaufen mit anderen gemeinsam")

    daten["bw"] = BW_GRENZE
    html = VORLAGE.replace("/*__DATEN__*/null", json.dumps(daten, ensure_ascii=False, separators=(",", ":")))
    AUSGABE.write_text(html, encoding="utf-8")
    print(f"Fertig: {AUSGABE}  ({AUSGABE.stat().st_size / 1e6:.1f} MB)")


